import type { App } from 'vue'
import type { RecentDrawing } from './types/recentDrawing'

let app: App | null = null
let mounting = false

/**
 * Read the recent drawings the PHP template embedded for the start page.
 *
 * The JSON is generated by the server, but it is still validated here so a
 * malformed value cannot break rendering.
 */
export function readRecentDrawings(container: HTMLElement): RecentDrawing[] {
  const raw = container.dataset.recentDrawings
  if (!raw) {
    return []
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    return []
  }

  if (!Array.isArray(parsed)) {
    return []
  }

  return parsed.filter((item): item is RecentDrawing => {
    const drawing = item as Partial<RecentDrawing> | null
    return (
      typeof drawing === 'object'
      && drawing !== null
      && typeof drawing.id === 'number'
      && typeof drawing.name === 'string'
      && typeof drawing.path === 'string'
      && typeof drawing.extension === 'string'
      && typeof drawing.mtime === 'number'
    )
  })
}

/**
 * Mount the CAD viewer into a container element.
 *
 * Vue and the viewer component are imported lazily so this module (which is
 * loaded as an init script on every Files page) stays small; the viewer
 * bundle is only fetched when the app's own page actually renders a
 * container.
 *
 * The file id is read from the container's `data-file-ids` attribute (set by
 * the PHP template) or from the `fileIds`/`fileId` query parameter.
 */
export async function mountCadViewerApp(container: HTMLElement): Promise<void> {
  if (app !== null || mounting) {
    return
  }
  mounting = true

  try {
    const [{ createApp }, { default: CadViewerApp }] = await Promise.all([
      import('vue'),
      import('./App.vue'),
    ])

    const fileId =
      container.dataset.fileIds ||
      new URLSearchParams(window.location.search).get('fileIds') ||
      new URLSearchParams(window.location.search).get('fileId') ||
      null

    app = createApp(CadViewerApp, { fileId })
    app.mount(container)
  } finally {
    mounting = false
  }
}

/**
 * Mount the start page (recent drawings + blank drawing creation).
 *
 * Loaded lazily like the viewer so the Files integration does not pay for it.
 */
export async function mountCadStartPage(container: HTMLElement): Promise<void> {
  if (app !== null || mounting) {
    return
  }
  mounting = true

  try {
    const [{ createApp }, { default: CadStartPage }] = await Promise.all([
      import('vue'),
      import('./StartPage.vue'),
    ])

    app = createApp(CadStartPage, { recent: readRecentDrawings(container) })
    app.mount(container)
  } finally {
    mounting = false
  }
}

